<?php require_once 'config/db.php'; $stories=$pdo->query("SELECT * FROM stories WHERE status='published' ORDER BY published_at DESC")->fetchAll(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DailyPost — Stories worth sharing.</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header><a class="brand" href="index.php">Daily<span>Post</span></a><span>Stories worth sharing.</span><nav><a href="#read">Read</a><a href="write.php">Write</a><a href="#newsletter">Newsletter</a></nav></header><div class="ticker">DAILYPOST · Ideas, stories and voices from people everywhere.</div><main><section class="hero"><div><small>TODAY</small><h1>A simple place<br>for good stories.</h1><p>Read what people are sharing. Write something worth remembering.</p><a class="button" href="write.php">Write a story →</a></div><div class="poster">READ.<br>WRITE.<br>SHARE.</div></section><section id="read"><div class="head"><h2>Latest Stories</h2><span><?=count($stories)?> stories</span></div><div class="grid"><?php foreach($stories as $s): ?><article class="card"><div class="art <?=htmlspecialchars($s['color'])?>"><?=htmlspecialchars(strtoupper(substr($s['title'],0,1)))?></div><div class="copy"><h3><?=htmlspecialchars($s['title'])?></h3><p><?=htmlspecialchars($s['excerpt'] ?: mb_substr($s['body'],0,150).'…')?></p><small>By <?=htmlspecialchars($s['author'])?> · <?=date('M j, Y',strtotime($s['published_at']))?></small><a class="read" href="story.php?id=<?=$s['id']?>">Read story →</a></div></article><?php endforeach; if(!$stories): ?><div class="empty">No stories published yet. <a href="write.php">Be the first to write.</a></div><?php endif; ?></div></section><section class="feature"><div><small>MOST READ</small><h2>Your next favorite story is waiting.</h2><p>Readers discover new voices every day.</p></div><div><small>EDITOR'S PICKS</small><h2>Small stories. Big ideas.</h2></div></section><section id="newsletter" class="newsletter"><small>NEWSLETTER</small><h2>One good email. Every day.</h2><form method="post" action="subscribe.php"><input type="email" name="email" required placeholder="you@example.com"><button>Subscribe</button></form></section></main><footer><b>DailyPost</b><span>Stories worth sharing.</span><small>© <?=date('Y')?> DailyPost</small></footer></body></html>